const g=new THREE.Group();
const outer=ctx.makeMat({color:'#ff9a3c',opacity:0.35,rough:0.4});
const inner=ctx.makeMat({color:'#d9480f',rough:0.5});
const spots=[[-2.4,-1.2,1.2, 0.6,0.2,0.9],[2.3,-1.6,-0.8, 1.2,0,0.4],[-1.8,1.9,-1.4, 0.3,0.8,1.3],[2.0,1.6,1.7, 1.0,0.5,0.2]];
for(const s of spots){
  const m=new THREE.Group(); m.position.set(s[0],s[1],s[2]); m.rotation.set(s[3],s[4],s[5]);
  m.add(new THREE.Mesh(new THREE.CapsuleGeometry(0.36,0.6,6,16),outer));
  for(let y=-0.4;y<=0.401;y+=0.16){
    const c=new THREE.Mesh(new THREE.CylinderGeometry(0.27,0.27,0.035,20),inner); c.position.y=y; m.add(c);
  }
  g.add(m);
}
return g;
